import { v4 as uuidv4 } from 'uuid';
import { putItem } from '/opt/nodejs/utils/dynamodb.js';
import { successResponse, errorResponse, parseJsonBody } from '/opt/nodejs/utils/response.js';

const snsClient = new SNSClient({});
const SNS_TOPIC_ARN = process.env.SNS_TOPIC_ARN!;

/**
 * Watch Part Lambda Function
 * Register alerts for desired parts
 */
export async function handler(event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> {
  try {
    const parsed = parseJsonBody(event);
    if (!parsed.ok) {
      return parsed.response;
    }
    const body = parsed.body;
    const { buyerId, email, phone, criteria } = body;

    // Validation
    if (!buyerId || !criteria) {
      return errorResponse('Missing required fields: buyerId, criteria', undefined, 400, event);
    }

    if (!email && !phone) {
      return errorResponse('At least one contact method (email or phone) is required', undefined, 400, event);
    }

    const watchId = uuidv4();
    const timestamp = new Date().toISOString();

    console.log('Creating watch:', watchId, JSON.stringify({ buyerId, criteria, client: event.headers?.['User-Agent'] ?? event.headers?.['user-agent'] }));

    // Store watch
    await putItem({
      PK: `WATCH#${watchId}`,
      SK: 'METADATA',
      buyerId,
      email: email || '',
      phone: phone || '',
      criteria,
      status: 'active',
      createdAt: timestamp,
      GSI1PK: `BUYER#${buyerId}`,
      GSI1SK: `STATUS#active#CREATED#${timestamp}`,
    });

    // Send confirmation
    await sendWatchConfirmation(email, criteria);

    return successResponse({
      message: 'Watch created successfully',
      watchId,
    }, 201, event);
  } catch (error: any) {
    console.error('Error in watch-part:', error);
    return errorResponse('Internal server error', error.message, 500, event);
  }
}

