import { APIGatewayProxyEvent, APIGatewayProxyResult } from 'aws-lambda';
import { SNSClient, PublishCommand } from '@aws-sdk/client-sns';
import { v4 as uuidv4 } from 'uuid';
import { putItem, queryGSI1WithPagination } from '/opt/nodejs/utils/dynamodb.js';
import { successResponse, errorResponse, parseJsonBody } from '/opt/nodejs/utils/response.js';

const snsClient = new SNSClient({});
const SNS_TOPIC_ARN = process.env.SNS_TOPIC_ARN!;

/**
 * Proposal Lambda Function
 * Handle B2B contract proposals
 */
export async function handler(event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> {
  try {
    const method = event.httpMethod;

    if (method === 'POST') {
      return await createProposal(event);
    } else if (method === 'GET') {
      return await getProposals(event);
    }

    return errorResponse('Method not allowed', undefined, 405, event);
  } catch (error: any) {
    console.error('Error in proposal:', error);
    return errorResponse('Internal server error', error.message, 500, event);
  }
}

/**
 * Create a new proposal
 */
async function createProposal(event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> {
  const parsed = parseJsonBody(event);
  if (!parsed.ok) {
    return parsed.response;
  }
  const body = parsed.body;
  const {
    fromCompanyId,
    toCompanyId,
    partIds,
    proposalType,
    message,
    quantity,
    priceOffer,
    terms,
  } = body;

  // Validation
  if (!fromCompanyId || !toCompanyId || !partIds || !proposalType) {
    return errorResponse(
      'Missing required fields: fromCompanyId, toCompanyId, partIds, proposalType',
      undefined,
      400,
      event
    );
  }

  const proposalId = uuidv4();
  const timestamp = new Date().toISOString();

  console.log('Creating proposal:', proposalId, JSON.stringify({ fromCompanyId, toCompanyId, proposalType, partIds: partIds.length }));

  // Store proposal
  await putItem({
    PK: `PROPOSAL#${proposalId}`,
    SK: 'METADATA',
    fromCompanyId,
    toCompanyId,
    partIds,
    proposalType,
    message: message || '',
    quantity: quantity || 1,
    priceOffer: priceOffer || 0,
    terms: terms || {},
    status: 'pending',
    createdAt: timestamp,
    GSI1PK: `COMPANY#${toCompanyId}`,
    GSI1SK: `STATUS#pending#CREATED#${timestamp}`,
  });

  // Send notification
  await sendProposalNotification(toCompanyId, proposalType, partIds);

  return successResponse({
    message: 'Proposal created successfully',
    proposalId,
  }, 201, event);
}

/**
 * Get proposals for a company
 */
async function getProposals(event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> {
  const { companyId, status, cursor, limit = '50' } = event.queryStringParameters || {};

  if (!companyId) {
    return errorResponse('companyId is required', undefined, 400, event);
  }

  let exclusiveStartKey: Record<string, any> | undefined;
  if (cursor) {
    try {
      exclusiveStartKey = JSON.parse(Buffer.from(cursor, 'base64').toString('utf-8'));
    } catch {
      return errorResponse('Invalid cursor', undefined, 400, event);
    }
  }

  // 받은 제안이 많은 회사도 끝까지 볼 수 있게 커서로 페이지를 넘긴다 (v1.11.2, 이전에는 최신 50건만 반환)
  const skPrefix = status ? `STATUS#${status}#` : '';
  const page = await queryGSI1WithPagination(`COMPANY#${companyId}`, skPrefix, Math.min(parseInt(limit) || 50, 100), exclusiveStartKey);
  const nextCursor = page.lastKey ? Buffer.from(JSON.stringify(page.lastKey)).toString('base64') : null;

  console.log('Returning proposals:', { companyId, status, count: page.items.length, nextCursor });

  // DynamoDB 내부 키들은 응답에서 제외
  const results = page.items.map(p => {
    const { PK, SK: _SK, GSI1PK: _GSI1PK, GSI1SK: _GSI1SK, ...data } = p;
    return {
      proposalId: PK.split('#')[1],
      ...data,
    };
  });

  return successResponse({
    proposals: results,
    count: results.length,
    nextCursor,
  }, 200, event);
}

/**
 * Send proposal notification
 */
async function sendProposalNotification(
  toCompanyId: string,
  proposalType: string,
  partIds: string[]
): Promise<void> {
  const typeText = proposalType === 'buy' ? '구매' : '판매';
  const message = `
[EECAR 계약 제안 도착]

회사 ID: ${toCompanyId}
제안 유형: ${typeText} 제안
관련 부품: ${partIds.length}개

자세한 내용은 플랫폼에서 확인해주세요.
  `.trim();

  try {
    await snsClient.send(
      new PublishCommand({
        TopicArn: SNS_TOPIC_ARN,
        Subject: `[EECAR] ${typeText} 제안이 도착했습니다`,
        Message: message,
      })
    );
  } catch (error) {
    console.error('Failed to send proposal notification:', error);
  }
}

